ICON='<svg class="brand-mark" viewBox="0 0 44 44" aria-hidden="true"><path d="M6 7h15v30H6zM23 7h15v30H23z" fill="none" stroke="currentColor" stroke-width="2"/><path d="M11 14h6m-6 6h6m-6 6h6M27 14h7m-7 6h7m-7 6h7" fill="none" stroke="currentColor" stroke-width="2"/></svg>'
def brand():return f'<a class="brand" href="/" aria-label="Solomon Grinds home">{ICON}<span><span class="brand-name">Solomon</span><span class="brand-sub">GRINDS · LUCAN</span></span></a>'
