def footer():
 return '<section class="cta-section dark"><div class="wrap"><div><div class="eyebrow">Your next step</div><h2>Let’s find the right<br>support for your student.</h2><p>Talk to Caitriona about subjects, class times and joining in person or online.</p></div>'+link('/contact-us/','Talk to Caitriona','light')+'</div></section><footer class="site-footer"><div class="wrap"><div class="footer-top"><div>'+brand()+'<p>Small-group grinds for Leaving Cert and Junior Cycle. Based in Lucan, supporting students across West Dublin and North Kildare.</p></div><div><h3>Find your support</h3><ul>'+''.join(f'<li><a href="{p}">{t}</a></li>' for p,t in [('/leaving-cert-grinds/','Leaving Cert grinds'),('/junior-cert-grinds/','Junior Cycle grinds'),('/oral-preparation/','Oral preparation'),('/easter-revision-leaving-junior-cert/','Easter revision'),('/timetable/','Timetable & weekly planner'),('/fees/','Fees')])+'</ul></div><div><h3>Come and say hello</h3><ul><li><a href="tel:+35316284171">01 628 4171</a></li><li><a href="tel:+353872745234">087 274 5234</a></li><li><a href="mailto:caitrionahayes@yahoo.ie">Email Caitriona</a></li><li><a href="/location/">Scoil Áine Naofa, Lucan</a></li><li><a href="/contact-us/">Contact & enquiries</a></li></ul></div></div><div class="footer-bottom"><span>© 2026 · Unofficial Solomon Grinds concept</span><span><a href="/privacy-statement/">Preview privacy</a> · <a href="/preview-notes/">Sources & corrections</a></span><a class="back-top" href="#top">Back to top ↑</a></div></div></footer>'
def page(path,title,description,body,foot=True):
 depth=path.strip('/').count('/')+(1 if path.strip('/') else 0)
 prefix='../'*depth
 # Relative URLs preserve functionality when served beneath a GitHub Pages project path.
 def relative(s):
  import re
  return re.sub(r'(href|src|action)="/([^\"]*)"',lambda m:m.group(1)+'="'+prefix+m.group(2)+'"',s)
 html='<!doctype html><html lang="en-IE"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="'+escape(description,quote=True)+'"><meta name="theme-color" content="#f7f4ed"><title>'+escape(title)+' | Solomon Grinds concept</title><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/bricolage.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/assets/site.css"><script src="/assets/gsap.min.js" defer></script><script src="/assets/ScrollTrigger.min.js" defer></script><link rel="stylesheet" href="/assets/creative.css"><script src="/assets/site.js" defer></script></head><body data-page="'+(path.strip('/') or 'home')+'">'+header(path)+'<main id="main">'+body+'</main>'+(footer() if foot else '')+'</body></html>'
 out=DIST/path.strip('/')/'index.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(relative(html))
def page_hero(label,title,description,actions='',notice=''):
 return f'<div class="page-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Home</a><span aria-hidden="true">/</span><span>{label}</span></div><div class="eyebrow">{label}</div><h1>{title}</h1><p class="lead">{description}</p>{actions}{notice}</div></div>'
def source(path,label='Published information'):
 return f'<p class="source-note">{label}: <a href="https://solomongrinds.ie{path}">Solomon Grinds’ existing website ↗</a>. Checked 11 October 2026. Confirm availability before joining.</p>'
def timetable(cycle=None,planner=False):
 rows=[r for r in CLASSES if not cycle or r['cycle']==cycle]
 title='Your subjects.<br>Your week.' if planner else 'The published weekly timetable.'
 content='<section class="section" id="weekly-classes"><div class="wrap"><div class="section-heading" data-reveal><div><div class="eyebrow">2026/27 · Wednesday & Saturday</div><h2>'+title+'</h2></div><p>Find a class, check the time and ask Caitriona about a place. Every slot below comes from Solomon’s published timetable.</p></div>'
 content+=f'<div class="timetable-shell" data-timetable data-default-cycle="{cycle or "lc"}"><div class="timetable-list"><div class="filters" hidden><div class="field"><label for="filter-cycle">Exam cycle</label><select id="filter-cycle"><option value="lc">Leaving Cert</option><option value="jc">Junior Cycle</option></select></div><div class="field"><label for="filter-subject">Subject</label><select id="filter-subject"><option value="all">All subjects</option></select></div><div class="field"><label for="filter-day">Day</label><select id="filter-day"><option value="all">Both days</option><option>Wednesday</option><option>Saturday</option></select></div></div><p class="results-count" aria-live="polite"></p>'
 for cyc in ['lc','jc']:
  cr=[r for r in rows if r['cycle']==cyc]
  if not cr:continue
  cname='Leaving Cert' if cyc=='lc' else 'Junior Cycle'
  content+=f'<div class="cycle-group" data-cycle-group="{cyc}"><h3 class="cycle-heading">{cname}</h3>'
  for day in ['Wednesday','Saturday']:
   content+=f'<div class="day-group" data-day-group="{day}"><h4 class="day-heading">{day}</h4><div class="class-grid">'
   for r in cr:
    if r['day']!=day:continue
    level=r['level'] if r['level']!='Common' else 'Junior Cycle'
    detail=(r['detail']+' · ' if r['detail'] else '')+level
    content+=f'<article class="class-row" data-class-id="{r["id"]}" data-cycle="{r["cycle"]}" data-subject="{escape(r["subject"],quote=True)}" data-day="{day}"><div class="class-time">{r["start"]}<span>– {r["end"]}</span></div><div><h5>{escape(r["subject"])}</h5><p>{detail}</p></div><button class="select-class" type="button" data-select-class="{r["id"]}" aria-pressed="false" aria-label="Add {escape(r["subject"],quote=True)} {detail} on {day} at {r["start"]} to your plan" hidden><span aria-hidden="true">+</span><span class="sr-only">Add class</span></button></article>'
   content+='</div></div>'
  content+='</div>'
 content+='<p class="empty-filter notice info" hidden>No published class matches these filters. Try another day or ask Caitriona about the subject.</p><noscript><p class="notice info">The full timetable is above. Enable JavaScript to filter classes and build a weekly plan, or call <a href="tel:+35316284171">01 628 4171</a>.</p></noscript></div>'
 if planner:
  content+='''<aside class="plan-panel" aria-labelledby="plan-title" hidden><div class="paper-kicker"><span>THE SOLOMON WEEK</span><span>2026/27</span></div><h3 id="plan-title">Make room<br>for your subjects.</h3><p class="plan-explanation">Choose up to three different subjects using the + buttons. The plan checks times before you enquire.</p><div data-plan-content><p class="plan-empty">Your week starts here.<br>Add a class from the timetable.</p></div><div class="plan-summary"><span data-plan-count>0 subjects selected</span><strong data-plan-price>€0</strong></div><p class="plan-rate-note">Weekly estimate · One class per subject.<br>€20 each, or €55 for three different subjects.</p><div class="plan-message" role="status" aria-live="polite"></div><a class="button plan-enquire" href="/contact-us/">Ask about this plan <span aria-hidden="true">↗</span></a><button class="clear-plan text-button" type="button">Clear my plan</button><p class="paper-footnote">Planning only. No place is reserved and no payment is taken. Class availability and the final fee are confirmed by Caitriona.</p></aside>'''
 if planner:content+='<div class="mobile-plan-summary" hidden><div><strong data-mobile-count>0 subjects</strong><span data-mobile-price>€0 / week</span></div><a href="#plan-title" class="button small">View my plan <span aria-hidden="true">↑</span></a></div>'
 content+='</div>'+source('/leaving-cert-grinds/' if cycle=='lc' else '/junior-cert-grinds/' if cycle=='jc' else '/leaving-cert-grinds/','Junior Cycle timetable' if cycle=='jc' else 'Leaving Cert timetable')
 if not cycle:content+=source('/junior-cert-grinds/','Junior Cycle timetable')
 content+='</div></section>'
 return content
def subject_index(cycle):
 subs=LC_SUBJECTS if cycle=='lc' else JC_SUBJECTS
 listed={r['subject'] for r in CLASSES if r['cycle']==cycle}
 return '<section class="section subject-section"><div class="wrap"><div class="section-heading" data-reveal><div><div class="eyebrow">Find your subject</div><h2>Start with what<br>you need help with.</h2></div><p>A broad subject list, with the published class times below. A subject without a time listed needs a quick conversation.</p></div><ul class="subject-index">'+''.join(f'<li><a href="/timetable/?cycle={cycle}&subject={s.replace(" & ","%20%26%20").replace(" ","%20")}"><span>{s}</span><span class="subject-index-meta">'+('View times <span aria-hidden="true">↗</span>' if s in listed else 'Ask for times <span aria-hidden="true">↗</span>')+'</span></a></li>' for s in subs)+'</ul>'+source('/leaving-cert-grinds/' if cycle=='lc' else '/junior-cert-grinds/')+'</div></section>'
def course_pages():
 for cyc,name,path,headline,copy in [('lc','Leaving Cert','/leaving-cert-grinds/','A clearer path<br>through the Leaving Cert.','Support for the subjects that need more time. Small-group grinds with an exam focus, in Lucan or through the published hybrid learning option.'),('jc','Junior Cycle','/junior-cert-grinds/','Build understanding.<br>Grow in confidence.','Extra time for questions, clearer explanations and focused subject support. Explore Solomon’s Junior Cycle classes and find a time that fits.')]:
  actions='<div class="hero-actions">'+link(f'/timetable/?cycle={cyc}','Plan your weekly classes')+'<a class="text-link" href="/fees/">See the fees</a></div>'
  body=page_hero(name,headline,copy,actions)+subject_index(cyc)+timetable(cyc)+'''<section class="section"><div class="wrap two-col"><div class="content-stack"><div class="eyebrow">Before you choose</div><h2>Find the right level,<br>then the right time.</h2><p>Some subjects have more than one class. The timetable distinguishes Higher, Ordinary and year-specific sessions where the business lists them.</p><p>Hybrid learning is advertised for students who cannot attend in person. Ask Caitriona whether your selected class is available online.</p></div><div class="content-stack"><h3>What happens next?</h3><ol class="rule-list"><li><span class="index">01</span><div><strong>Choose your subject and level</strong>Use the published timetable to identify a class.</div></li><li><span class="index">02</span><div><strong>Talk to Caitriona</strong>Confirm that the class suits your student and that a place is available.</div></li><li><span class="index">03</span><div><strong>Confirm the practical details</strong>Agree attendance, payment and the first class directly with Solomon.</div></li></ol></div></div></section>'''
  page(path,name+' grinds — subjects & timetable',f'Published 2026/27 {name} subjects and class times at Solomon Grinds in Lucan. Unofficial website concept.',body)
